$ErrorActionPreference = 'Stop'

try {
    Write-Host 'Fetching Firefly IPs from API...'

    $response = Invoke-RestMethod `
        -Uri "$($Env:FIREFLY_API_BASE)/v2/infrastructure/public-nat-ips" `
        -Method Get `
        -TimeoutSec 30

    if ($response -and $response.ips -and $response.ips.Count -gt 0) {
        Write-Host "Successfully fetched $($response.ips.Count) IPs from API"
        $ipsArray = $response.ips
    }
    else {
        Write-Warning 'API response was empty or invalid, using fallback IPs'
        $ipsArray = $Env:FALLBACK_IPS | ConvertFrom-Json
    }
}
catch {
    Write-Warning "Failed to fetch IPs from API: $($_.Exception.Message)"
    Write-Host 'Using fallback IPs'
    $ipsArray = $Env:FALLBACK_IPS | ConvertFrom-Json
}

$DeploymentScriptOutputs = @{}
$DeploymentScriptOutputs['ips'] = $ipsArray

Write-Host "Output IPs: $($ipsArray -join ', ')"

# Authenticate as the template's diagnostics identity: Firefly's service principal is read-only and
# cannot write diagnostic settings. Signing in again is how a client picks up new role assignments,
# so the discovery retry loop below reuses this.
function Connect-DeploymentIdentity {
    $azContext = Connect-AzAccount -Identity -AccountId $Env:IDENTITY_CLIENT_ID -ErrorAction Stop
    # Pin the hub subscription. The default one may sit outside the management group, and
    # Get-AzManagementGroup fails there when Microsoft.Management is not registered.
    Set-AzContext -SubscriptionId $Env:SUBSCRIPTION_ID -ErrorAction Stop | Out-Null
    return $azContext
}

Write-Host "Authenticating with Azure..."
try {
    $azContext = Connect-DeploymentIdentity
    Write-Host "Successfully authenticated with Azure. Tenant: $($azContext.Context.Tenant.Id)"
} catch {
    throw "Azure authentication failed: $($_.Exception.Message)"
}

# Get all subscriptions under the management group and create diagnostic settings
Write-Host "Setting up diagnostic settings for all subscriptions under management group: $Env:MANAGEMENT_GROUP_ID"

# Role assignments can take up to 10 minutes to take effect, so retry for ~10 minutes,
# signing in again before each retry.
$maxAttempts = 20
$retryDelaySeconds = 30
$mgHierarchy = $null
for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
    try {
        $mgHierarchy = Get-AzManagementGroup -GroupName $Env:MANAGEMENT_GROUP_ID -Expand -Recurse -ErrorAction Stop
        break
    } catch {
        Write-Warning "Attempt $attempt of ${maxAttempts}: Get-AzManagementGroup failed: $($_.Exception.Message)"
        if ($attempt -lt $maxAttempts) {
            Start-Sleep -Seconds $retryDelaySeconds
            try { Connect-DeploymentIdentity | Out-Null } catch { Write-Warning "Re-login failed: $($_.Exception.Message)" }
        }
    }
}

if (-not $mgHierarchy) {
    throw "Could not read management group '$Env:MANAGEMENT_GROUP_ID' after $maxAttempts attempts. The diagnostics identity needs Monitoring Contributor on the management group."
}

try {
    # The Management Groups API reports child groups as 'Microsoft.Management/managementGroups';
    # older responses used '/providers/Microsoft.Management/managementGroups'. Accept both.
    function Get-SubscriptionIds($node) {
        $subscriptionIds = @()
        if ($node.Children) {
            foreach ($child in $node.Children) {
                if ($child.Type -eq '/subscriptions') {
                    $subscriptionIds += $child.Name
                } elseif ($child.Type -match 'Microsoft\.Management/managementGroups$') {
                    $subscriptionIds += Get-SubscriptionIds $child
                }
            }
        }
        return $subscriptionIds
    }

    $allSubscriptionIds = Get-SubscriptionIds $mgHierarchy
    Write-Host "Found $($allSubscriptionIds.Count) subscriptions to configure"

    $successCount = 0
    $failedSubscriptions = @()

    foreach ($subId in $allSubscriptionIds) {
        try {
            Write-Host "Setting up diagnostic settings for subscription: $subId"

            # Switch to the subscription context
            Set-AzContext -SubscriptionId $subId -ErrorAction Stop | Out-Null

            # Check if diagnostic setting already exists
            $existingDiagnostics = Get-AzDiagnosticSetting -ResourceId "/subscriptions/$subId" -ErrorAction SilentlyContinue
            $diagnosticName = "firefly-mg-diagnostics-$subId"

            if ($existingDiagnostics | Where-Object { $_.Name -eq $diagnosticName }) {
                Write-Host "Diagnostic setting already exists for subscription $subId, updating..."
            } else {
                Write-Host "Creating new diagnostic setting for subscription $subId"
            }

            # Create/Update diagnostic setting for subscription activity logs.
            # Set-AzDiagnosticSetting parameters differ between Az.Monitor versions (Az 8.1 has no -Log),
            # so call the REST API directly with the same api-version as the MG-level setting.
            $categories = @('Administrative', 'Security', 'ServiceHealth', 'Alert', 'Recommendation', 'Policy', 'Autoscale', 'ResourceHealth')
            $body = @{
                properties = @{
                    storageAccountId = $Env:STORAGE_ACCOUNT_ID
                    logs = @($categories | ForEach-Object { @{ category = $_; enabled = $true } })
                }
            } | ConvertTo-Json -Depth 5

            # The identity's role assignments are created in this same deployment, so a 403 can just mean
            # they have not propagated yet. Retry with a fresh sign-in, as for discovery above.
            $path = "/subscriptions/$subId/providers/Microsoft.Insights/diagnosticSettings/$($diagnosticName)?api-version=2021-05-01-preview"
            for ($putAttempt = 1; $putAttempt -le $maxAttempts; $putAttempt++) {
                $response = Invoke-AzRestMethod -Method PUT -Path $path -Payload $body
                if ($response.StatusCode -ne 403 -or $putAttempt -eq $maxAttempts) { break }
                Write-Warning "Attempt $putAttempt of ${maxAttempts}: diagnostic setting write for $subId returned 403, retrying"
                Start-Sleep -Seconds $retryDelaySeconds
                try { Connect-DeploymentIdentity | Out-Null; Set-AzContext -SubscriptionId $subId -ErrorAction Stop | Out-Null } catch { Write-Warning "Re-login failed: $($_.Exception.Message)" }
            }

            if ($response.StatusCode -in 200, 201) {
                Write-Host "✓ Successfully configured diagnostic settings for subscription $subId"
                $successCount++
            } else {
                Write-Warning "Failed to configure diagnostic settings for subscription $subId (HTTP $($response.StatusCode)): $($response.Content)"
                $failedSubscriptions += $subId
            }

        } catch {
            Write-Warning "Error configuring diagnostic settings for subscription $subId : $($_.Exception.Message)"
            $failedSubscriptions += $subId
        }
    }

    Write-Host "`n=== DIAGNOSTIC SETTINGS SUMMARY ==="
    Write-Host "Total subscriptions: $($allSubscriptionIds.Count)"
    Write-Host "Successfully configured: $successCount"
    Write-Host "Failed: $($failedSubscriptions.Count)"

    if ($failedSubscriptions.Count -gt 0) {
        Write-Host "Failed subscriptions: $($failedSubscriptions -join ', ')"
    }

} catch {
    throw "Failed to configure diagnostic settings: $($_.Exception.Message)"
}

if ($successCount -eq 0 -and $allSubscriptionIds.Count -gt 0) {
    throw "Diagnostic settings failed for all $($allSubscriptionIds.Count) subscriptions"
}

Write-Host "Diagnostic settings configuration completed"

# Authenticate with Firefly
Write-Host "Authenticating with Firefly API..."
try {
    $authBody = @{
        accessKey = $Env:FIREFLY_ACCESS_KEY
        secretKey = $Env:FIREFLY_SECRET_KEY
    } | ConvertTo-Json -Compress

    $tokenResp = Invoke-WebRequest -SkipCertificateCheck -ContentType 'application/json' -Method Post -Uri "$($Env:FIREFLY_PROD_API_BASE)/api/account/access_keys/login" -Body $authBody
    $tokenObj = $tokenResp.Content | ConvertFrom-Json
    $jwt = $tokenObj.access_token

    if (-not $jwt) { 
        throw 'Failed to obtain access token from Firefly API'
    }
    Write-Host "Successfully authenticated with Firefly API"
} catch {
    throw "Firefly authentication failed: $($_.Exception.Message)"
}

# Login to Azure. Signing in again is how a client picks up new role assignments,
# so the discovery retry loop below reuses this.
function Connect-ServicePrincipal {
    $securePassword = ConvertTo-SecureString $Env:CLIENT_SECRET -AsPlainText -Force
    $credential = New-Object System.Management.Automation.PSCredential($Env:CLIENT_ID, $securePassword)
    $azContext = Connect-AzAccount -ServicePrincipal -Credential $credential -Tenant $Env:TENANT_ID -ErrorAction Stop
    Set-AzContext -SubscriptionId $Env:SUBSCRIPTION_ID -ErrorAction Stop | Out-Null
    return $azContext
}

Write-Host "Logging into Azure..."
try {
    $azContext = Connect-ServicePrincipal
    Write-Host "Successfully logged into Azure. Tenant: $($azContext.Context.Tenant.Id), subscription context: $Env:SUBSCRIPTION_ID"
} catch {
    throw "Azure authentication failed: $($_.Exception.Message)"
}

# Function to extract subscription IDs from hierarchy.
# The Management Groups API reports child groups as 'Microsoft.Management/managementGroups';
# older responses used '/providers/Microsoft.Management/managementGroups'. Accept both.
function Get-SubscriptionIdsFromHierarchy($node) {
    $subscriptionIds = @()
    if ($node.Children) {
        foreach ($child in $node.Children) {
            if ($child.Type -eq '/subscriptions') {
                $subscriptionIds += $child.Name
                Write-Host "Found subscription in MG: $($child.DisplayName) ($($child.Name))"
            } elseif ($child.Type -match 'Microsoft\.Management/managementGroups$') {
                Write-Host "Processing child management group: $($child.DisplayName)"
                $subscriptionIds += Get-SubscriptionIdsFromHierarchy $child
            }
        }
    }
    return $subscriptionIds
}

# Sanitize a name for Firefly: allowed chars are letters, digits, space, and _:.@/+,-
# Anything else gets replaced with '-'. Runs of '-' collapsed; leading/trailing '-' trimmed.
# Empty result falls back to the supplied default.
function Get-SanitizedFireflyName($name, $fallback) {
    $sanitized = [regex]::Replace($name, '[^A-Za-z0-9 _:.@/+,-]', '-')
    $sanitized = [regex]::Replace($sanitized, '-{2,}', '-').Trim('-').Trim()
    $sanitized = [regex]::Replace($sanitized, '^[^A-Za-z0-9]+', '')
    if ([string]::IsNullOrWhiteSpace($sanitized)) { return $fallback }
    return $sanitized
}

# Get all subscriptions under the management group using Get-AzManagementGroup
Write-Host "Discovering subscriptions under management group: $Env:MANAGEMENT_GROUP_ID"
$allSubscriptionIds = @()

# Role assignments can take up to 10 minutes to take effect, so retry for ~10 minutes,
# signing in again before each retry. Never fall back to a partial subscription list:
# Flow 2 is only correct if the whole hierarchy is discovered.
$maxAttempts = 20
$retryDelaySeconds = 30
$mgHierarchy = $null
for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
    try {
        $mgHierarchy = Get-AzManagementGroup -GroupName $Env:MANAGEMENT_GROUP_ID -Expand -Recurse -ErrorAction Stop
        break
    } catch {
        Write-Warning "Attempt $attempt of ${maxAttempts}: Get-AzManagementGroup failed: $($_.Exception.Message)"
        if ($attempt -lt $maxAttempts) {
            Start-Sleep -Seconds $retryDelaySeconds
            try { Connect-ServicePrincipal | Out-Null } catch { Write-Warning "Re-login failed: $($_.Exception.Message)" }
        }
    }
}

if (-not $mgHierarchy) {
    throw "Could not read management group '$Env:MANAGEMENT_GROUP_ID' after $maxAttempts attempts. The service principal needs Reader or Management Group Reader on the management group. No subscriptions were registered."
}

Write-Host "Successfully retrieved management group hierarchy for: $($mgHierarchy.DisplayName) (attempt $attempt)"
$allSubscriptionIds = @(Get-SubscriptionIdsFromHierarchy $mgHierarchy)

Write-Host "Found $($allSubscriptionIds.Count) total subscriptions to process"

$registeredSubscriptionIds = @()
$skippedSubscriptionIds = @()
$failedSubscriptions = @()

# Surfaced through the deployment outputs (az deployment mg show --query properties.outputs)
function Set-IntegrationOutputs {
    $script:DeploymentScriptOutputs = @{}
    $script:DeploymentScriptOutputs['managementGroupId'] = $Env:MANAGEMENT_GROUP_ID
    $script:DeploymentScriptOutputs['subscriptionsDiscovered'] = $allSubscriptionIds.Count
    $script:DeploymentScriptOutputs['subscriptionsRegistered'] = $registeredSubscriptionIds.Count
    $script:DeploymentScriptOutputs['subscriptionsSkipped'] = $skippedSubscriptionIds.Count
    $script:DeploymentScriptOutputs['subscriptionsFailed'] = $failedSubscriptions.Count
    $script:DeploymentScriptOutputs['registeredSubscriptionIds'] = @($registeredSubscriptionIds)
    $script:DeploymentScriptOutputs['skippedSubscriptionIds'] = @($skippedSubscriptionIds)
    $script:DeploymentScriptOutputs['failedSubscriptionIds'] = @($failedSubscriptions | ForEach-Object { $_.Id })
}

if ($allSubscriptionIds.Count -eq 0) {
    Write-Warning "No subscriptions found under management group $Env:MANAGEMENT_GROUP_ID"
    Set-IntegrationOutputs
    exit 0
}

$headers = @{ 
    'Authorization' = "Bearer $jwt"
    'Content-Type' = 'application/json'
    'Accept' = 'application/json'
}
$successCount = 0

# Process each subscription individually
foreach ($subId in $allSubscriptionIds) {
    try {
        Write-Host "Processing subscription: $subId"

        # Get subscription details
        $subscription = $null
        try {
            $subscription = Get-AzSubscription -SubscriptionId $subId -ErrorAction Stop
            $subscriptionDisplayName = $subscription.Name
            Write-Host "Subscription details - Name: $subscriptionDisplayName, State: $($subscription.State)"
        } catch {
            Write-Warning "Could not retrieve subscription details for $subId. Using ID as name."
            $subscriptionDisplayName = $subId
        }

        # Skip disabled subscriptions
        if ($subscription -and $subscription.State -eq 'Disabled') {
            Write-Warning "Skipping disabled subscription: $subscriptionDisplayName ($subId)"
            $skippedSubscriptionIds += $subId
            continue
        }

        # Sanitize name for Firefly's allowed character set
        $sanitizedName = Get-SanitizedFireflyName -name $subscriptionDisplayName -fallback $subId
        if ($sanitizedName -ne $subscriptionDisplayName) {
            Write-Host "Sanitized integration name: '$subscriptionDisplayName' -> '$sanitizedName'"
        }

        Write-Host "Creating Firefly integration for subscription: $sanitizedName ($subId)"

        # Prepare integration payload
        $integrationPayload = [ordered]@{
            subscriptionId = $subId
            tenantId = $Env:TENANT_ID
            applicationId = $Env:CLIENT_ID
            clientSecret = $Env:CLIENT_SECRET
            name = "$sanitizedName"
            directoryDomain = $Env:DIRECTORY_DOMAIN
            isProd = [bool]::Parse($Env:IS_PROD)
            isEventDriven = [bool]::Parse($Env:IS_EVENT_DRIVEN)
            isAutoDiscover = [bool]::Parse($Env:IS_AUTO_DISCOVER)
            isIacAutoDiscoveryDisabled = $false
        }

        $jsonPayload = $integrationPayload | ConvertTo-Json -Compress
        Write-Host "Payload: $jsonPayload"

        # Make API call to create integration
        try {
            $apiResponse = Invoke-WebRequest -UseBasicParsing -SkipCertificateCheck -Method Post -Uri "$($Env:FIREFLY_PROD_API_BASE)/api/integrations/azure?onConflictUpdate=true" -Headers $headers -Body $jsonPayload -ErrorAction Stop

            if ($apiResponse.StatusCode -eq 200 -or $apiResponse.StatusCode -eq 201) {
                # The Firefly API can return 200 with a ValidationError body. Detect that.
                $respBody = $null
                try { $respBody = $apiResponse.Content | ConvertFrom-Json } catch { }
                if ($respBody -and $respBody.integration -and $respBody.integration.type -eq 'ValidationError') {
                    $errMsg = "Firefly rejected integration: $($respBody.integration.message)"
                    Write-Warning "$errMsg (subscription $sanitizedName, $subId)"
                    $failedSubscriptions += @{Id=$subId; Name=$sanitizedName; Reason=$errMsg}
                    Start-Sleep -Milliseconds 500
                    continue
                }
                Write-Host "Successfully created integration for subscription: $sanitizedName ($subId)"
                $successCount++
                $registeredSubscriptionIds += $subId
            } else {
                Write-Warning "Unexpected status code $($apiResponse.StatusCode) for subscription $sanitizedName ($subId)"
                Write-Host "Response: $($apiResponse.Content)"
                $failedSubscriptions += @{Id=$subId; Name=$sanitizedName; Reason="HTTP $($apiResponse.StatusCode)"}
            }
        } catch {
            $errorMsg = $_.Exception.Message
            if ($_.ErrorDetails.Message) {
                $errorMsg += " | Response: $($_.ErrorDetails.Message)"
            }
            Write-Warning "Failed to create integration for subscription $sanitizedName ($subId): $errorMsg"
            $failedSubscriptions += @{Id=$subId; Name=$sanitizedName; Reason=$errorMsg}
        }

        # Small delay to avoid rate limiting
        Start-Sleep -Milliseconds 500

    } catch {
        Write-Warning "Error processing subscription $subId : $($_.Exception.Message)"
        $failedSubscriptions += @{Id=$subId; Name=$subId; Reason=$_.Exception.Message}
    }
}

# Summary
Write-Host "`n=== INTEGRATION SUMMARY ==="
Write-Host "Total subscriptions found: $($allSubscriptionIds.Count)"
Write-Host "Successful integrations: $successCount"
Write-Host "Skipped (disabled): $($skippedSubscriptionIds.Count)"
Write-Host "Failed integrations: $($failedSubscriptions.Count)"

if ($failedSubscriptions.Count -gt 0) {
    Write-Host "`nFailed subscriptions:"
    $failedSubscriptions | ForEach-Object { 
        Write-Host " - $($_.Name) ($($_.Id)) - Reason: $($_.Reason)" 
    }
}

Set-IntegrationOutputs

if ($successCount -eq 0 -and $allSubscriptionIds.Count -gt 0) {
    throw "All subscription integrations failed"
} elseif ($successCount -gt 0) {
    Write-Host "Integration process completed successfully with $successCount successful integrations"
} else {
    Write-Host "No subscriptions were processed"
}
